#[rustfmt::skip]
#[test]
fn active_root_guidance_uses_cortex_skill_authority() -> anyhow::Result<()> { let root = std::env::var_os("NOOK_REPO_ROOT").map_or_else(|| std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(".."), std::path::PathBuf::from); anyhow::ensure!(!root.join("skills-lock.json").exists(), "external skill registry must remain retired"); let readme = std::fs::read_to_string(root.join("README.md"))?; anyhow::ensure!(readme.contains("Project skill semantics live only in team-owned Markdown under `.cortex`") && readme.contains("task loom:cortex-audit"), "README must route project skill semantics and validation through Cortex and Loom"); let obsolete = [".agents/skills", ".cursor/skills", ".claude/skills", "task skills:", "task impeccable:", "design-taste-frontend"]; for path in ["README.md", "AGENTS.md", ".codex/hooks.json", "CODEX.md", ".cursor/rules.md"] { let content = std::fs::read_to_string(root.join(path))?; for marker in obsolete { anyhow::ensure!(!content.contains(marker), "active authority input {path} references obsolete `{marker}` machinery"); } } let mut pending = vec![root.join(".github/prompts")]; while let Some(directory) = pending.pop() { for entry in std::fs::read_dir(directory)? { let path = entry?.path(); if path.is_dir() { pending.push(path); } else { let content = std::fs::read_to_string(&path)?; for marker in obsolete { anyhow::ensure!(!content.contains(marker), "hosted prompt {} references obsolete `{marker}` machinery", path.display()); } } } } Ok(()) }
